// Keep the workers.dev preview out of search while allowing the custom domain to index.
// @ts-ignore Generated by the Cloudflare build, not present in a normal Next build.
import worker from "./.open-next/worker.js";
import { blockedIncidentSource, formRequestRejection } from "./lib/formAbuse";
import { onchainSupplyContracts, type OnchainSupplyObservation } from "./lib/onchainSupply";

type Database = {
  prepare(query: string): {
    bind(...values: (string | number)[]): {
      all<T>(): Promise<{ results: T[] }>;
      run(): Promise<unknown>;
    };
  };
};

type WorkerEnv = {
  ASSETS: { fetch(request: Request): Promise<Response> };
  WORKER_SELF_REFERENCE: { fetch(request: Request): Promise<Response> };
  FORM_RATE_LIMITER: { limit(options: { key: string }): Promise<{ success: boolean }> };
  NETWORK_DB: Database;
};

async function rpc(url: string, method: string, params: unknown[]): Promise<string | Record<string, string>> {
  const response = await fetch(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params }),
    signal: AbortSignal.timeout(10000)
  });
  if (!response.ok) throw new Error(`RPC ${method} returned HTTP ${response.status}`);
  const payload = await response.json() as { result?: string | Record<string, string>; error?: { message?: string } };
  if (!payload.result || payload.error) throw new Error(`RPC ${method}: ${payload.error?.message || "missing result"}`);
  return payload.result;
}

async function captureSupply(env: WorkerEnv) {
  const day = new Date().toISOString().slice(0, 10);
  const existing = await env.NETWORK_DB.prepare("SELECT asset_id FROM onchain_supply_observations WHERE day = ?")
    .bind(day).all<{ asset_id: string }>();
  const recorded = new Set(existing.results.map(row => row.asset_id));
  const missing = onchainSupplyContracts.filter(contract => !recorded.has(contract.id));
  for (const contract of missing) {
    const endpoints: string[] = [contract.rpc];
    if ("fallbackRpc" in contract) endpoints.push(contract.fallbackRpc);
    let reading: { blockNumber: number; timestamp: number; rawSupply: string; decimals: number } | null = null;
    for (const endpoint of endpoints) {
      try {
        const chainId = await rpc(endpoint, "eth_chainId", []) as string;
        if (Number(BigInt(chainId)) !== contract.chainId) throw new Error("chain ID mismatch");
        const blockHex = await rpc(endpoint, "eth_blockNumber", []) as string;
        if (!/^0x[0-9a-f]+$/i.test(blockHex)) throw new Error("invalid block number");
        const block = await rpc(endpoint, "eth_getBlockByNumber", [blockHex, false]) as Record<string, string>;
        const timestamp = Number(BigInt(block.timestamp));
        if (!Number.isFinite(timestamp) || Math.abs(Date.now() / 1000 - timestamp) > 7200) throw new Error("stale block");
        const supplyHex = await rpc(endpoint, "eth_call", [{ to: contract.address, data: "0x18160ddd" }, blockHex]) as string;
        const decimalsHex = await rpc(endpoint, "eth_call", [{ to: contract.address, data: "0x313ce567" }, blockHex]) as string;
        const decimals = Number(BigInt(decimalsHex));
        const rawSupply = BigInt(supplyHex).toString();
        if (decimals !== contract.decimals || BigInt(rawSupply) <= BigInt(0)) throw new Error("decimals or supply mismatch");
        reading = { blockNumber: Number(BigInt(blockHex)), timestamp, rawSupply, decimals };
        break;
      } catch (error) {
        console.warn(`Supply read failed for ${contract.id} via ${new URL(endpoint).hostname}:`, error);
      }
    }
    if (!reading) {
      console.error(`Supply capture failed for ${contract.id} on all configured RPC endpoints`);
      continue;
    }
    try {
      await env.NETWORK_DB.prepare(`INSERT OR IGNORE INTO onchain_supply_observations
        (asset_id, day, chain_id, contract_address, raw_supply, decimals, block_number, block_timestamp, observed_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`).bind(
          contract.id, day, contract.chainId, contract.address, reading.rawSupply, reading.decimals,
          reading.blockNumber, reading.timestamp, new Date().toISOString()
        ).run();
    } catch (error) {
      console.error(`Supply database write failed for ${contract.id}:`, error);
    }
  }
}

async function supplyResponse(env: WorkerEnv): Promise<Response> {
  try {
    const series = await Promise.all(onchainSupplyContracts.map(async contract => {
      const result = await env.NETWORK_DB.prepare("SELECT * FROM onchain_supply_observations WHERE asset_id = ? ORDER BY day DESC LIMIT 400")
        .bind(contract.id).all<OnchainSupplyObservation>();
      return { ...contract, observations: result.results.reverse() };
    }));
    return Response.json({ metric: "ERC-20 totalSupply in native token units", method: "Read totalSupply() and decimals() at the same recorded chain block; divide raw supply by 10^decimals. This is not circulating supply, fiat reserves, market capitalization, or a global market total.", series }, {
      headers: { "Cache-Control": "public, max-age=900" }
    });
  } catch (error) {
    console.error("Supply history unavailable:", error);
    return Response.json({ error: "Supply history is temporarily unavailable" }, { status: 503, headers: { "Cache-Control": "no-store" } });
  }
}

export default {
  async fetch(request: Request, env: WorkerEnv, context: unknown) {
    const url = new URL(request.url);
    if (blockedIncidentSource(request)) {
      return Response.json({ ok: false, code: "request_rejected", message: "This request could not be accepted." }, { status: 403 });
    }
    const intakePaths = ["/api/vendor-intro-request", "/api/vendor-comparison-lead", "/api/tokenization-assessment", "/api/family-office-stack-assessment", "/api/freelancer-contact-request", "/api/freelancer-marketplace-waitlist", "/api/freelancer-profile"];
    if (request.method === "POST" && intakePaths.includes(url.pathname)) {
      const rejection = formRequestRejection(request);
      if (rejection) return Response.json({ ok: false, code: rejection, message: "Please reload the form and try again, or email contact@fluidrwa.com." }, { status: rejection === "request_too_large" ? 413 : 403 });
      const ip = request.headers.get("cf-connecting-ip");
      if (ip && env.FORM_RATE_LIMITER) {
        try {
          const { success } = await env.FORM_RATE_LIMITER.limit({ key: `fluidrwa-form:${ip}` });
          if (!success) return Response.json({ ok: false, code: "submission_rate_limit", message: "Too many attempts. Please wait one minute and try again. Your details are still in the form." }, { status: 429, headers: { "Retry-After": "60", "Cache-Control": "no-store" } });
        } catch {
          // Preserve lead delivery during limiter outages; payload checks still run in the API.
          console.error("form rate limiter unavailable");
        }
      }
    }
    if (url.hostname === "fluidrwa.com") {
      url.hostname = "www.fluidrwa.com";
      return Response.redirect(url.toString(), 308);
    }
    if (request.method === "GET" && url.pathname === "/api/network-explorer/onchain-supply") {
      return supplyResponse(env);
    }

    const image = url.pathname === "/_next/image" ? url.searchParams.get("url") : null;
    // Serve local originals until Cloudflare image transformation is configured.
    const localImage = image && image.startsWith("/assets/") && !image.includes("..") && !image.includes("\\");
    const response = localImage
      ? await env.ASSETS.fetch(new Request(new URL(image, url.origin), { method: request.method }))
      : await worker.fetch(request, env, context);
    if (!url.hostname.endsWith(".workers.dev")) return response;

    const headers = new Headers(response.headers);
    headers.set("X-Robots-Tag", "noindex, nofollow");
    return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
  },

  async scheduled(
    _controller: unknown,
    env: WorkerEnv,
    context: { waitUntil(promise: Promise<unknown>): void }
  ) {
    context.waitUntil(
      env.WORKER_SELF_REFERENCE.fetch(new Request("https://www.fluidrwa.com/api/market-signals/ingest")).then((response) => {
        if (!response.ok) throw new Error(`Market signal ingestion failed: HTTP ${response.status}`);
      })
    );
    context.waitUntil(captureSupply(env).catch(error => {
      console.error("Supply capture unavailable:", error);
    }));
  }
};
